    """Given a list of positive integers, find the intersection of all possible sublists."""

### Solution:


    intersection = set(numbers)

    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)+1):
            sublist = numbers[i:j]
            if all(x in sublist for x in intersection):
                intersection = set(sublist)

    return list(intersection)

