def create_dict_from_list(list1, list2):

    """Given two lists of equal length, create a dictionary where the elements from list1 are used as keys,
    and the elements from list2 are used as values. The order of the elements should be maintained."""

### Solution:


    # Check if the length of both lists are equal
    if len(list1) == len(list2):

        # Using range and list comprehension to create a dictionary
        result_dict = {list1[i]: list2[i] for i in range(len(list1))}

        return result_dict

    else:
        return "Error: The lists must have equal length."

